"""
Sanitization and secret-redaction utilities for the intelligence layer.

HARD RULES ENFORCED:
1. Untrusted attacker inputs (user agent, headers, path, body) are sanitized
   and never formatted as instructions.
2. Secrets are NEVER passed to LLMs or logged; secrets are redacted before
   any summarization or external dispatch.
"""

import re
from collections.abc import Mapping
from typing import Any

# Patterns matching sensitive tokens, AWS keys, Stripe keys, passwords, bearer tokens
_SECRET_PATTERNS = [
    # Honeytokens generated by service: honey_<base64/urlsafe>
    (re.compile(r"honey_[A-Za-z0-9_\-]{16,}", re.IGNORECASE), "[REDACTED_HONEYTOKEN]"),
    # AWS Access Key IDs
    (re.compile(r"\b(AKIA|ABIA|ACCA|ASIA)[0-9A-Z]{16}\b"), "[REDACTED_AWS_KEY]"),
    # AWS Secret Access Keys (approximate 40 chars base64)
    (re.compile(r"(?i)(aws_secret_access_key|secret_key|secretkey)[\s:=]+['\"]?([A-Za-z0-9/+=]{40})['\"]?"), r"\1=[REDACTED_AWS_SECRET]"),
    # Stripe keys: sk_live_..., sk_test_...
    (re.compile(r"\b(sk_live|sk_test|rk_live|rk_test)_[0-9a-zA-Z]{24,}\b"), "[REDACTED_STRIPE_KEY]"),
    # Generic API Keys / Bearer tokens
    (re.compile(r"(?i)bearer\s+[A-Za-z0-9_\-\.]{16,}"), "Bearer [REDACTED_BEARER_TOKEN]"),
    # Connection strings with credentials
    (re.compile(r"://([^:]+):([^@]+)@"), "://[USER]:[REDACTED_PASSWORD]@"),
]

# Patterns for prompt injection neutralization
_PROMPT_INJECTION_PATTERNS = [
    re.compile(r"(?i)ignore\s+(all\s+)?(previous|prior)\s+instructions"),
    re.compile(r"(?i)system\s*prompt"),
    re.compile(r"(?i)you\s+are\s+now\s+a"),
    re.compile(r"(?i)disregard\s+all"),
    re.compile(r"(?i)reveal\s+your\s+instructions"),
    re.compile(r"(?i)<\/?system>"),
    re.compile(r"(?i)<\/?instruction>"),
]


# Sensitive headers that must NEVER be persisted or logged
SENSITIVE_HEADER_NAMES = {
    "authorization",
    "cookie",
    "set-cookie",
    "proxy-authorization",
    "x-admin-token",
    "x-api-key",
    "token",
    "secret",
}


def sanitize_headers(headers: Any) -> dict:
    """
    Sanitize and filter HTTP request headers for forensic persistence.
    - Explicitly strips sensitive credentials (Authorization, Cookie, API keys, Admin tokens).
    - Redacts any remaining secret patterns from values.
    - Limits header name and value lengths.
    """
    if not headers or not isinstance(headers, Mapping):
        return {}

    sanitized = {}
    for key, val in headers.items():
        if not key or not isinstance(key, str):
            continue
        key_lower = key.strip().lower()
        if key_lower in SENSITIVE_HEADER_NAMES:
            continue
        # Also drop any header key containing suspicious auth tokens
        if any(bad in key_lower for bad in ["auth", "cookie", "token", "secret", "password"]):
            continue

        val_str = str(val) if val is not None else ""
        clean_val = sanitize_untrusted_text(val_str, max_length=500)
        sanitized[key_lower] = clean_val

    return sanitized


def redact_secrets(text: str) -> str:
    """
    Scrub any secret keys, API credentials, passwords, or honeytokens from text.
    Ensures that secrets are never sent to external LLMs, logs, or plain text previews.
    """
    if not text or not isinstance(text, str):
        return ""

    redacted = text
    for pattern, replacement in _SECRET_PATTERNS:
        redacted = pattern.sub(replacement, redacted)
    return redacted


def sanitize_untrusted_text(text: Any, max_length: int = 300) -> str:
    """
    Sanitize untrusted, attacker-controlled strings (e.g. user agent, path, headers).
    - Converts non-strings safely
    - Strips non-printable and control characters
    - Truncates to max_length
    - Neutralizes common prompt injection attack phrases
    - Strips dangerous HTML/template tags
    """
    if text is None:
        return ""

    if not isinstance(text, str):
        text = str(text)

    # Redact any secrets first
    clean = redact_secrets(text)

    # Disarm prompt injection phrases
    for pattern in _PROMPT_INJECTION_PATTERNS:
        clean = pattern.sub("[FILTERED_PROMPT_INJECTION]", clean)

    # Replace newlines and carriage returns with spaces to prevent log/header splitting
    clean = clean.replace("\r", " ").replace("\n", " ")

    # Strip non-printable ASCII and non-whitelisted characters
    clean = re.sub(r"[\x00-\x1f\x7f-\x9f]", "", clean)

    # Strip dangerous HTML tags
    clean = re.sub(r"<[^>]*>", "", clean)

    # Truncate
    clean = clean.strip()
    if len(clean) > max_length:
        suffix = " [TRUNCATED]"
        cut_len = max(0, max_length - len(suffix))
        clean = clean[:cut_len] + suffix

    return clean
